    while True:
        resp=apis.spotify.show_playlist_library(access_token=token, query='', is_public=is_public, page_index=page_index, page_limit=20, sort_by=None)
        if not resp:
            break
        if isinstance(resp, dict) and 'message' in resp:
            raise RuntimeError(resp)
        all_pl.extend(resp)
        page_index += 1
    return all_pl

